From 9af9691eb5189dea9f3a8d84e7aa49b71e6119a0 Mon Sep 17 00:00:00 2001
From: =?UTF-8?q?Niccol=C3=B2=20Venerandi?= <niccolo@venerandi.com>
Date: Sat, 21 Nov 2026 17:53:54 +0100
Subject: [PATCH] applets/notes: allow choosing a custom text color

The text color of a sticky note was fixed by its color scheme, so the
transparent notes could be unreadable over a dark or busy wallpaper. Add
a custom text color option, used for the note's text and buttons.

BUG: 526305
---
 applets/notes/main.xml                 |  8 ++++++++
 applets/notes/qml/configAppearance.qml | 21 ++++++++++++++++++++-
 applets/notes/qml/main.qml             |  4 +++-
 3 files changed, 31 insertions(+), 2 deletions(-)

diff --git a/applets/notes/main.xml b/applets/notes/main.xml
index 552e3c2fd..a04729c6e 100644
--- a/applets/notes/main.xml
+++ b/applets/notes/main.xml
@@ -11,6 +11,14 @@
       <default>yellow</default>
     </entry>

+    <entry name="useCustomTextColor" type="Bool">
+      <default>false</default>
+    </entry>
+
+    <entry name="customTextColor" type="Color">
+      <default>#ffffff</default>
+    </entry>
+
     <entry name="fontSize" type="int">
     </entry>

diff --git a/applets/notes/qml/configAppearance.qml b/applets/notes/qml/configAppearance.qml
index 724afb1ab..dbed4d25e 100644
--- a/applets/notes/qml/configAppearance.qml
+++ b/applets/notes/qml/configAppearance.qml
@@ -12,11 +12,14 @@ import org.kde.plasma.core as PlasmaCore
 import org.kde.plasma.plasmoid
 import org.kde.kirigami as Kirigami
 import org.kde.ksvg as KSvg
+import org.kde.kquickcontrols as KQuickControls

 KCM.GridViewKCM {
     id: kcm
     property string cfg_color
     property alias cfg_fontSize: fontSizeSpinBox.value
+    property alias cfg_useCustomTextColor: useCustomTextColorCheckBox.checked
+    property alias cfg_customTextColor: customTextColorButton.color

     readonly property bool inPanel: [PlasmaCore.Types.TopEdge, PlasmaCore.Types.RightEdge,PlasmaCore.Types.BottomEdge, PlasmaCore.Types.LeftEdge].includes(Plasmoid.location)

@@ -39,6 +42,20 @@ KCM.GridViewKCM {
                     }
                 }
             }
+
+            Kirigami.FormEntry {
+                title: i18nc("@label", "Text color:")
+                contentItem: QQC2.CheckBox {
+                    id: useCustomTextColorCheckBox
+                    text: i18nc("@option:check", "Custom")
+                }
+                trailingItems: [
+                    KQuickControls.ColorButton {
+                        id: customTextColorButton
+                        enabled: useCustomTextColorCheckBox.checked
+                    }
+                ]
+            }
         }
     }

@@ -112,7 +129,9 @@ KCM.GridViewKCM {
                     //this is deliberately _NOT_ the theme color as we are over a known bright background
                     //an unknown colour over a known colour is a bad move as you end up with white on yellow
                     color: {
-                        if (kcm.inPanel && delegate.modelData === "translucent") {
+                        if (kcm.cfg_useCustomTextColor) {
+                            return kcm.cfg_customTextColor;
+                        } else if (kcm.inPanel && delegate.modelData === "translucent") {
                             return Kirigami.Theme.textColor;
                         } else if (delegate.modelData === "black" || delegate.modelData === "translucent-light") {
                             return "#dfdfdf"
diff --git a/applets/notes/qml/main.qml b/applets/notes/qml/main.qml
index f07705ade..f607bfdba 100644
--- a/applets/notes/qml/main.qml
+++ b/applets/notes/qml/main.qml
@@ -50,7 +50,9 @@ PlasmoidItem {
     // except in a panel when it is translucent, the panel background is used, so we use the normal text color.
     // an unknown colour over a known colour is a bad move as you end up with white on yellow.
     readonly property color textIconColor: {
-        if (noBackground) {
+        if (Plasmoid.configuration.useCustomTextColor) {
+            return Plasmoid.configuration.customTextColor;
+        } else if (noBackground) {
             return Kirigami.Theme.textColor;
         } else if (Plasmoid.configuration.color === "black" || Plasmoid.configuration.color === "translucent-light") {
             return "#dfdfdf";
-- 
2.53.0
